def validate_quote(quote, now, max_age):
    if now - quote["timestamp"] > max_age or quote["price"] <= 0:
        raise ValueError("Invalid or stale quote")
    return quote["price"]

def order_notional(quantity, price):
    if quantity <= 0:
        raise ValueError("Quantity must be positive")
    return quantity * price

def prepare_order(quantity, quote, now, max_age, limit):
    price = validate_quote(quote, now, max_age)
    notional = order_notional(quantity, price)
    check_order_limit(notional, limit)
    return {"quantity": quantity, "price": price, "notional": notional, "status": "draft"}

def validate_position(position, price, total, ceiling):
